        kept_length = len(kept_rows)
        rotated_rows = kept_rows[final_state % kept_length:] + kept_rows[:final_state % kept_length]
    else:
        rotated_rows = []
        final_state = 0

    total_quantity = 0
    earliest_expiry = None

    for row in rotated_rows:
        if isinstance(row, list) and len(row) == 2:
            try:
                expiry = int(row[0])
                quantity = int(row[1])
                if expiry > today:
                    total_quantity += quantity
